import dedent from 'dedent-js';

import { format as originalFormat, FormatFn } from '../src/sqlFormatter.js';

import supportsCreateTable from './features/createTable.js';
import supportsDropTable from './features/dropTable.js';
import supportsJoin from './features/join.js';
import supportsOperators, { standardOperators } from './features/operators.js';
import supportsSchema from './features/schema.js';
import supportsStrings from './features/strings.js';
import supportsConstraints from './features/constraints.js';
import supportsIdentifiers from './features/identifiers.js';
import supportsParams from './options/param.js';
import supportsSetOperations from './features/setOperations.js';
import supportsLimiting from './features/limiting.js';
import supportsUpdate from './features/update.js';
import supportsTruncateTable from './features/truncateTable.js';
import supportsCreateView from './features/createView.js';
import supportsIsDistinctFrom from './features/isDistinctFrom.js';
import supportsArrayLiterals from './features/arrayLiterals.js';
import supportsDataTypeCase from './options/dataTypeCase.js';
import behavesLikePostgresqlFormatter from './behavesLikePostgresqlFormatter.js';

describe('PostgreSqlFormatter', () => {
  const language = 'postgresql';
  const format: FormatFn = (query, cfg = {}) => originalFormat(query, { ...cfg, language });

  behavesLikePostgresqlFormatter(format);
  supportsCreateView(format, { orReplace: true, materialized: true, ifNotExists: true });
  supportsCreateTable(format, { ifNotExists: true });
  supportsDropTable(format, { ifExists: true });
  supportsConstraints(format, ['NO ACTION', 'RESTRICT', 'CASCADE', 'SET NULL', 'SET DEFAULT']);
  supportsArrayLiterals(format, { withArrayPrefix: true });
  supportsUpdate(format, { whereCurrentOf: true });
  supportsTruncateTable(format, { withoutTable: true });
  supportsStrings(format, ["''-qq", "U&''", "X''", "B''", "E''", '$$']);
  supportsIdentifiers(format, [`""-qq`, 'U&""']);
  supportsSchema(format);
  // Missing: '::' type cast (tested separately)
  supportsOperators(
    format,
    [
      ...standardOperators,
      // Arithmetic
      '%',
      '^',
      '|/',
      '||/',
      '@',
      // Assignment
      ':=',
      // Bitwise
      '&',
      '|',
      '#',
      '~',
      '<<',
      '>>',
      // Byte comparison
      '~>~',
      '~<~',
      '~>=~',
      '~<=~',
      // Geometric
      '@-@',
      '@@',
      '##',
      '<->',
      '&&',
      '&<',
      '&>',
      '<<|',
      '&<|',
      '|>>',
      '|&>',
      '<^',
      '>^',
      '?#',
      '?-',
      '?|',
      '?-|',
      '?||',
      '@>',
      '<@',
      '<@>',
      '~=',
      // JSON
      '?',
      '@?',
      '?&',
      '->',
      '->>',
      '#>',
      '#>>',
      '#-',
      // Named function params
      '=>',
      // Network address
      '>>=',
      '<<=',
      // Pattern matching
      '~~',
      '~~*',
      '!~~',
      '!~~*',
      // POSIX RegExp
      '~',
      '~*',
      '!~',
      '!~*',
      // Range/multirange
      '-|-',
      // String concatenation
      '||',
      // Text search
      '@@@',
      '!!',
      '^@',
      // Trigram/trigraph
      '<%',
      '<<%',
      '%>',
      '%>>',
      '<<->',
      '<->>',
      '<<<->',
      '<->>>',
      // Cube
      '~>',
      // Hstore
      '#=',
      // Custom operators: from pgvector extension
      '<#>',
      '<=>',
      '<+>',
      '<~>',
      '<%>',
      // Custom operators: from PostGIS extension
      '&&&',
      '|=|',
    ],
    { any: true }
  );
  supportsIsDistinctFrom(format);
  supportsJoin(format);
  supportsSetOperations(format);
  supportsParams(format, { numbered: ['$'] });
  supportsLimiting(format, { limit: true, offset: true, fetchFirst: true, fetchNext: true });
  supportsDataTypeCase(format);

  // Regression test for issue #935
  it('preserves pg_dump restrict commands', () => {
    const result = format(
      '\\restrict AbC123\ncreate table widgets(id integer);\n\\unrestrict AbC123'
    );

    expect(result).toBe(dedent`
      \\restrict AbC123
      create table widgets (id integer);

      \\unrestrict AbC123
    `);
    expect(format(result)).toBe(result);
  });

  // Regression test for issue #624
  it('supports array slice operator', () => {
    expect(format('SELECT foo[:5], bar[1:], baz[1:5], zap[:];')).toBe(dedent`
      SELECT
        foo[:5],
        bar[1:],
        baz[1:5],
        zap[:];
    `);
  });

  // Regression test for issue #447
  it('formats empty SELECT', () => {
    expect(format('SELECT;')).toBe(dedent`
      SELECT;
    `);
  });

  // Regression test for issues #391 and #618
  // PostgreSQL-specific variations of WITH TIME ZONE syntax
  it('formats TIMESTAMP WITH TIME ZONE syntax', () => {
    expect(
      format(
        `create table time_table (id int,
          created_at timestamp without time zone,
          deleted_at time with time zone,
          modified_at timestamp(0) with time zone);`,
        { dataTypeCase: 'upper' }
      )
    ).toBe(dedent`
      create table time_table (
        id INT,
        created_at TIMESTAMP WITHOUT TIME ZONE,
        deleted_at TIME WITH TIME ZONE,
        modified_at TIMESTAMP(0) WITH TIME ZONE
      );
    `);
  });

  it('formats FOR UPDATE clause', () => {
    expect(
      format(`
        SELECT * FROM tbl FOR UPDATE;
        SELECT * FROM tbl FOR UPDATE OF tbl.salary;
      `)
    ).toBe(dedent`
      SELECT
        *
      FROM
        tbl
      FOR UPDATE;

      SELECT
        *
      FROM
        tbl
      FOR UPDATE OF
        tbl.salary;
    `);
  });

  // Issue #711
  it('supports OPERATOR() syntax', () => {
    expect(format(`SELECT foo OPERATOR(public.===) bar;`)).toBe(dedent`
      SELECT
        foo OPERATOR(public.===) bar;
    `);
    expect(format(`SELECT foo operator ( !== ) bar;`)).toBe(dedent`
      SELECT
        foo operator ( !== ) bar;
    `);
  });

  it('keeps spaces around OPERATOR() syntax with denseOperators', () => {
    // Densing "foo OPERATOR(public.===) bar" into "fooOPERATOR(public.===)bar"
    // glues the operands onto the keyword and re-parses as invalid SQL.
    expect(format(`SELECT foo OPERATOR(public.===) bar;`, { denseOperators: true })).toBe(dedent`
      SELECT
        foo OPERATOR(public.===) bar;
    `);
    expect(format(`SELECT a OPERATOR(+) b;`, { denseOperators: true })).toBe(dedent`
      SELECT
        a OPERATOR(+) b;
    `);
  });

  // Issue #813
  it('supports OR REPLACE in CREATE FUNCTION', () => {
    expect(format(`CREATE OR REPLACE FUNCTION foo ();`)).toBe(dedent`
      CREATE OR REPLACE FUNCTION foo ();
    `);
  });

  it('formats JSON and JSONB data types', () => {
    expect(
      format(`CREATE TABLE foo (bar json, baz jsonb);`, {
        dataTypeCase: 'upper',
      })
    ).toBe('CREATE TABLE foo (bar JSON, baz JSONB);');
  });

  // Issue #850
  it('supports OR REPLACE in CREATE PROCEDURE', () => {
    expect(format(`CREATE OR REPLACE PROCEDURE foo () LANGUAGE sql AS $$ BEGIN END $$;`)).toBe(
      dedent`CREATE OR REPLACE PROCEDURE foo () LANGUAGE sql AS $$ BEGIN END $$;`
    );
  });

  // Issue #876
  it('supports UUID type and functions', () => {
    expect(
      format(`CREATE TABLE foo (id uuid DEFAULT Gen_Random_Uuid());`, {
        dataTypeCase: 'upper',
        functionCase: 'lower',
      })
    ).toBe(dedent`CREATE TABLE foo (id UUID DEFAULT gen_random_uuid());`);
  });

  // Issue #924
  it('formats keywords in COMMENT ON', () => {
    expect(format(`comment on table foo is 'Hello my table';`, { keywordCase: 'upper' })).toBe(
      dedent`COMMENT ON TABLE foo IS 'Hello my table';`
    );
  });

  it('formats keywords in CREATE CONSTRAINT TRIGGER', () => {
    expect(
      format(
        `create constraint trigger Example_Trigger
        after insert
        or
        update of Column_A,
        Column_B on Example_Table
        deferrable initially deferred for each row
        execute procedure Example_Function ();`,
        { keywordCase: 'upper', identifierCase: 'lower' }
      )
    ).toBe(dedent`
      CREATE CONSTRAINT TRIGGER example_trigger
      AFTER INSERT OR UPDATE OF column_a,
      column_b ON example_table
      DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
      EXECUTE PROCEDURE example_function ();
    `);
  });

  it('formats multiple CREATE TRIGGER events without treating OR as a logical operator', () => {
    expect(
      format(
        `create trigger Example_Trigger
        after insert or update or delete on Example_Table
        for each row
        execute function Example_Function ();`,
        { keywordCase: 'upper', identifierCase: 'lower' }
      )
    ).toBe(dedent`
      CREATE TRIGGER example_trigger
      AFTER INSERT OR UPDATE OR DELETE ON example_table FOR EACH ROW
      EXECUTE FUNCTION example_function ();
    `);
  });
});

test/transactsql.test.ts.source:
import dedent from 'dedent-js';

import { format as originalFormat, FormatFn } from '../src/sqlFormatter.js';
import behavesLikeSqlFormatter from './behavesLikeSqlFormatter.js';

import supportsCreateTable from './features/createTable.js';
import supportsDropTable from './features/dropTable.js';
import supportsAlterTable from './features/alterTable.js';
import supportsStrings from './features/strings.js';
import supportsBetween from './features/between.js';
import supportsOperators, { standardOperators } from './features/operators.js';
import supportsJoin from './features/join.js';
import supportsConstraints from './features/constraints.js';
import supportsDeleteFrom from './features/deleteFrom.js';
import supportsComments from './features/comments.js';
import supportsIdentifiers from './features/identifiers.js';
import supportsParams from './options/param.js';
import supportsWindow from './features/window.js';
import supportsSetOperations from './features/setOperations.js';
import supportsLimiting from './features/limiting.js';
import supportsInsertInto from './features/insertInto.js';
import supportsUpdate from './features/update.js';
import supportsTruncateTable from './features/truncateTable.js';
import supportsMergeInto from './features/mergeInto.js';
import supportsCreateView from './features/createView.js';
import supportsDataTypeCase from './options/dataTypeCase.js';
import supportsNumbers from './features/numbers.js';

describe('TransactSqlFormatter', () => {
  const language = 'transactsql';
  const format: FormatFn = (query, cfg = {}) => originalFormat(query, { ...cfg, language });

  behavesLikeSqlFormatter(format);
  supportsNumbers(format);
  supportsComments(format, { nestedBlockComments: true });
  supportsCreateView(format, { materialized: true });
  supportsCreateTable(format);
  supportsDropTable(format, { ifExists: true });
  supportsConstraints(format, ['SET NULL', 'SET DEFAULT', 'CASCADE', 'NO ACTION']);
  supportsAlterTable(format, {
    dropColumn: true,
  });
  supportsDeleteFrom(format);
  supportsInsertInto(format, { withoutInto: true });
  supportsUpdate(format, { whereCurrentOf: true });
  supportsTruncateTable(format);
  supportsMergeInto(format);
  supportsStrings(format, ["N''", "''-qq"]);
  supportsIdentifiers(format, [`""-qq`, '[]']);
  supportsBetween(format);
  // Missing: `::` scope resolution operator (tested separately)
  supportsOperators(
    format,
    [
      ...standardOperators,
      '%',
      '&',
      '|',
      '^',
      '~',
      '!<',
      '!>',
      '+=',
      '-=',
      '*=',
      '/=',
      '%=',
      '|=',
      '&=',
      '^=',
    ],
    { any: true }
  );
  supportsJoin(format, { without: ['NATURAL'], supportsUsing: false, supportsApply: true });
  supportsSetOperations(format, ['UNION', 'UNION ALL', 'EXCEPT', 'INTERSECT']);
  supportsParams(format, { named: ['@'], quoted: ['@""', '@[]'] });
  supportsWindow(format);
  supportsLimiting(format, { offset: true, fetchFirst: true, fetchNext: true });
  supportsDataTypeCase(format);

  it('supports language:tsql alias', () => {
    const result = originalFormat('SELECT [my column] FROM [my table];', { language: 'tsql' });
    expect(result).toBe(dedent`
      SELECT
        [my column]
      FROM
        [my table];
    `);
  });

  it('recognizes @, $, # as part of identifiers', () => {
    const result = format('SELECT from@bar, where#to, join$me FROM tbl;');
    expect(result).toBe(dedent`
      SELECT
        from@bar,
        where#to,
        join$me
      FROM
        tbl;
    `);
  });

  it('allows @ and # at the start of identifiers', () => {
    const result = format('SELECT @bar, #baz, @@some, ##flam FROM tbl;');
    expect(result).toBe(dedent`
      SELECT
        @bar,
        #baz,
        @@some,
        ##flam
      FROM
        tbl;
    `);
  });

  it('formats scope resolution operator without spaces', () => {
    expect(format('SELECT hierarchyid :: GetRoot();')).toBe(dedent`
      SELECT
        hierarchyid::GetRoot ();
    `);
  });

  it('formats .. shorthand for database.schema.table', () => {
    expect(format('SELECT x FROM db..tbl')).toBe(dedent`
      SELECT
        x
      FROM
        db..tbl
    `);
  });

  it('formats ALTER TABLE ... ALTER COLUMN', () => {
    expect(format(`ALTER TABLE t ALTER COLUMN foo INT NOT NULL DEFAULT 5;`)).toBe(dedent`
      ALTER TABLE t
      ALTER COLUMN foo INT NOT NULL DEFAULT 5;
    `);
  });

  it('formats GO CREATE OR ALTER PROCEDURE', () => {
    const result = format('GO CREATE OR ALTER PROCEDURE p');
    expect(result).toBe(dedent`
      GO
      CREATE OR ALTER PROCEDURE p
    `);
  });

  it('formats SELECT ... INTO clause', () => {
    const result = format('SELECT col INTO #temp FROM tbl');
    expect(result).toBe(dedent`
      SELECT
        col
      INTO
        #temp
      FROM
        tbl
    `);
  });

  it('formats SELECT ... OPTION ()', () => {
    const result = format('SELECT col OPTION (MAXRECURSION 5)');
    expect(result).toBe(dedent`
      SELECT
        col
      OPTION
        (MAXRECURSION 5)
    `);
  });

  it('formats SELECT ... FOR BROWSE', () => {
    expect(format('SELECT col FOR BROWSE')).toBe(dedent`
      SELECT
        col
      FOR BROWSE
    `);
  });

  it('formats SELECT ... FOR XML', () => {
    expect(format("SELECT col FOR XML PATH('Employee'), ROOT('Employees')")).toBe(dedent`
      SELECT
        col
      FOR XML
        PATH ('Employee'),
        ROOT ('Employees')
    `);
  });

  it('formats SELECT ... FOR JSON', () => {
    expect(format('SELECT col FOR JSON PATH, WITHOUT_ARRAY_WRAPPER')).toBe(dedent`
      SELECT
        col
      FOR JSON
        PATH,
        WITHOUT_ARRAY_WRAPPER
    `);
  });

  it('formats goto labels', () => {
    const result = format(
      `InfiniLoop:
      SELECT 'Hello.';
      GOTO InfiniLoop;`
    );
    expect(result).toBe(dedent`
      InfiniLoop:
      SELECT
        'Hello.';

      GOTO InfiniLoop;
    `);
  });

  // Issue #811
  it('does not detect CHAR() as function', () => {
    expect(format(`CREATE TABLE foo (name char(65));`, { functionCase: 'upper' })).toBe(dedent`
      CREATE TABLE foo (name char(65));
    `);
  });

  // Issue #810
  it('supports special $ACTION keyword', () => {
    expect(format(`MERGE INTO tbl OUTPUT $action AS act;`)).toBe(dedent`
      MERGE INTO
        tbl OUTPUT $action AS act;
    `);
  });

  // Issue #814
  it('formats GO on a separate line', () => {
    expect(format(`CREATE VIEW foo AS SELECT * FROM tbl GO CREATE INDEX bar`)).toBe(dedent`
      CREATE VIEW foo AS
      SELECT
        *
      FROM
        tbl
      GO
      CREATE INDEX bar
    `);
  });

  // Issue #903
  it('supports ALTER PROCEDURE', () => {
    expect(format(`GO ALTER PROCEDURE foo AS SELECT 1; GO`)).toBe(dedent`
      GO
      ALTER PROCEDURE foo AS
      SELECT
        1;

      GO
    `);
  });

  // Issue #819
  it('does not recognize ODBC keywords as reserved keywords', () => {
    expect(format(`SELECT Value, Zone`, { keywordCase: 'upper' })).toBe(dedent`
      SELECT
        Value,
        Zone
    `);
  });

  // Issue #877
  it('allows the use of the ODBC date format', () => {
    const result = format(
      `WITH [sales_query] AS (SELECT [customerId] FROM [segments].dbo.[sales] WHERE [salesdate] > {d'2024-01-01'})`
    );
